#!/usr/bin/env python3
"""Render measured TeX tables from the aggregate and qualified native cases."""
import argparse,json
from collections import Counter
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--summary',type=Path,required=True);p.add_argument('--qualification',type=Path,required=True);p.add_argument('--out',type=Path,required=True);a=p.parse_args()
d=json.loads(a.summary.read_text());q=json.loads(a.qualification.read_text())
if d['observed']!=d['scheduled']:raise ValueError('Incomplete main cohort')
def frac(x):
 if x['unknown']:return str(x['true'])+'/'+str(x['n'])+'?'
 return str(x['true'])+'/'+str(x['n'])
lines=[r'% Generated by scripts/render_pga_tables.py from measured records.',r'\newcommand{\pgaMeasuredPrimary}{%',r'\begin{table*}[t]',r'\centering\footnotesize',
 r'\caption{Exploratory AgentDojo development results: three clean, six attacked and six benign content-removal controls per configuration. Utilities and ASR are counts. PV records confirmed structural-mutation violations only; $A_1$ is attacked assessment-unknown. No read/final-disclosure guarantee is tested. Times are descriptive, with staggered execution.}',
 r'\label{tab:primary-results}',r'\begin{tabular*}{\textwidth}{@{\extracolsep{\fill}}lrrrrrrrrr@{}}',r'\toprule',
 r'Method & $U_0$ & $U_1$ & $U_s$ & ASR & PV$_0$ & PV$_1$ & $A_1$ & Auto. queries & Time (s) \\',r'\midrule']
for r in d['arms']:
 c,b,s=r['clean'],r['attack'],r['sham'];name=r['label']
 if r['arm']=='pga':name=r'\textbf{PGA active (ours)}'
 vals=[name,frac(c['utility']),frac(b['utility']),frac(s['utility']),frac(b['asr']),f"{c['structural_violations']}/{c['n']}",f"{b['structural_violations']}/{b['n']}",f"{b['assessment_unknown']}/{b['n']}",f"{b['mean_collectors']:.2f}",f"{r['all']['mean_seconds']:.2f}"]
 lines.append(' & '.join(vals)+r' \\')
lines += [r'\bottomrule',r'\end{tabular*}',r'\end{table*}}',r'\newcommand{\pgaMeasuredQualification}{%',r'\begin{table}[t]',r'\centering\footnotesize',
 r'\caption{Native interface qualification on 15 constructed development controls per configuration. These 60 cases are not model episodes or an attack-rate estimate. Unresolved identity and budget cases remain in the counts.}',r'\label{tab:mechanism-results}',r'\begin{tabularx}{\columnwidth}{@{}Lrrrr@{}}',r'\toprule',r'Configuration & Allow & Deny & Unresolved & PV \\',r'\midrule']
for arm,label in [('static','Static'),('acquire_all','Acquire-all'),('adaptive_sop','Adaptive SOP'),('pga',r'\textbf{PGA active}')]:
 rows=[r for r in q['cases'] if r['arm']==arm];v=Counter(r['final_decision']['verdict'] for r in rows)
 lines.append(' & '.join([label,str(v['allow']),str(v['deny']),str(v['unresolved']),str(sum(bool(r['effect_score']['violation']) for r in rows))])+r' \\')
lines += [r'\bottomrule',r'\end{tabularx}',r'\end{table}}']
a.out.write_text('\n'.join(lines)+'\n')
